#!/bin/sh
# Create the `automerge` path dependency the oracle crate compiles against.
#
# The oracle is a Cargo crate which depends on the upstream Rust implementation
# by path. That path is a machine specific absolute location, so it is wired up
# with symlinks generated by this script rather than committed. They point into
# the checkout named by `$AUTOMERGE_REF`, which is read only and never
# modified.
#
# The script is idempotent. It refuses to create anything when `AUTOMERGE_REF`
# is unset or does not point at a checkout, so a missing environment never
# leaves a dangling symlink behind.
#
# POSIX sh, because the build runner invokes it as `sh tools/link-oracle.sh`.

set -eu

# Directory holding this script, so the vendor tree is found no matter what the
# working directory is.
script_dir=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)

vendor_dir="$script_dir/oracle/vendor"

# The cargo workspace inside the reference checkout, relative to
# `$AUTOMERGE_REF`.
crate_relpath="rust"

# The crates which must be visible in `vendor/`. `automerge` is the reference
# implementation itself. Cargo resolves the path dependencies of a path
# dependency relative to the symlink path rather than the symlink target, so
# the rest of the closure the manifests reach has to be linked in too:
# `automerge` depends on `hexane` and on `automerge-test` as a dev dependency,
# and `automerge-test` depends back on `automerge`.
crates="automerge hexane automerge-test"

if [ -z "${AUTOMERGE_REF:-}" ]; then
    echo "link-oracle.sh: AUTOMERGE_REF is not set; it must name an automerge checkout" >&2
    exit 1
fi

# Check every target before writing anything, so a bad environment leaves no
# half linked vendor tree behind.
for crate in $crates; do
    if [ ! -d "$AUTOMERGE_REF/$crate_relpath/$crate" ]; then
        echo "link-oracle.sh: $AUTOMERGE_REF/$crate_relpath/$crate is not a directory; is AUTOMERGE_REF correct?" >&2
        exit 1
    fi
done

mkdir -p "$vendor_dir"

for crate in $crates; do
    link_path="$vendor_dir/$crate"
    target="$AUTOMERGE_REF/$crate_relpath/$crate"
    # Already pointing at the right place: nothing to do.
    if [ -L "$link_path" ] && [ "$(readlink "$link_path")" = "$target" ]; then
        continue
    fi
    # Either a symlink to somewhere else or a real checkout. Both are replaced.
    rm -rf "$link_path"
    ln -s "$target" "$link_path"
done
